package jsbuiltin

import "testing"

// TestToLowerCaseMatchesV8 holds ToLowerCase to node's String.prototype.toLowerCase
// (v22.20.0) on mixed strings — an ASCII capital BEFORE a rune the
// stdlib lowers differently is the case that once took the ASCII fast path.
// Generated by running the strings through node; not hand-written.
func TestToLowerCaseMatchesV8(t *testing.T) {
	for _, c := range []struct{ in, want string }{
		{"S14-\u0130\u03a3.example", "s14-i\u0307\u03c3.example"},
		{"A\u0130", "ai\u0307"},
		{"\u0130A", "i\u0307a"},
		{"AB\u03a3", "ab\u03c2"},
		{"X-\u03a3", "x-\u03c3"},
		{"Hello W\u00d6RLD", "hello w\u00f6rld"},
		{"abc", "abc"},
		{"ABC", "abc"},
		{"\u0130", "i\u0307"},
		{"A\u03a3 B", "a\u03c2 b"},
		{"A\u03a3.b", "a\u03c3.b"},
		{"ZZ\ua7ce", "zz\ua7ce"},
		{"a\u0130", "ai\u0307"},
		{"Z\u00c9", "z\u00e9"},
	} {
		if got := ToLowerCase(c.in); got != c.want {
			t.Errorf("ToLowerCase(%q) = %q, V8 gives %q", c.in, got, c.want)
		}
	}
}
